    java.util.Scanner sc = new java.util.Scanner(System.in);
    long n = sc.nextLong();
    int len = String.valueOf(n).length();
    long m = 998244353;
    long req = mexp(10, len, m);
    long num = (mexp(req, n, m) - 1 + m) % m;
    long den = modInverse(req - 1, m);
    System.out.println(mul(n, mul(num, den, m), m));
